-- Juggernaut Death
-- items: 17833, 17898, 17399, 18976
function Juggernaut_Death(e)
  if not eq.get_entity_list():IsMobSpawnedByNpcTypeID(89193) then
     local clist = eq.get_entity_list():GetClientList();
     if ( clist ~= nil ) then
		 for currclient in clist.entries do
			if(currclient:GetClass() == Class.BERSERKER) then
				local qglobals = eq.get_qglobals(currclient);
				if(qglobals["berserk_epic"] == "3" and qglobals["berserker_seb"] == nil) then
					eq.spawn2(89194, 0, 0, -225.93, -1556.52, -173.84, 320); -- needs_heading_validation
					eq.spawn2(89195, 0, 0, -214, -1572, -173.84, 110); -- NPC: A_Sebilite_Guardian
					eq.spawn2(89195, 0, 0, -214, -1538, -173.84, 152); -- NPC: A_Sebilite_Guardian
					eq.set_global("berserker_seb","1",3,"H2");
					return; --only spawn 1
				end
			end
		 end
	 end
  end
end

function Protector_Spawn(e)
	eq.set_timer("depop", 30*60*1000); --30min
	eq.set_next_hp_event(75);
end

function Guardian_Spawn(e)
	eq.set_timer("depop", 30*60*1000); --30min
end

function Protector_Timer(e)
	if(e.timer=="depop") then
		eq.stop_timer("depop");
		eq.depop_all(89194); --protector
		eq.depop_all(89195); --guardian
	elseif(e.timer=="nuke") then
		e.self:CastSpell(2047, e.self:GetTarget():GetID()); -- Spell: Death Shackles
	elseif(e.timer=="checkaxe") then
			e.self:ForeachHateList(
				function(ent, hate, damage, frenzy)
					if(ent:IsClient()) then
						if(ent:CastToMob():GetClass() == Class.BERSERKER and damage > 0) then --berserker
							local currclient=ent:CastToClient();
							if(math.random(3)==1) then 
								if(currclient:GetItemIDAt(Slot.Primary)==16779) then
									eq.target_global("berserk_epic_test17759", "1", "F", 0,currclient:CharacterID(),0);
									currclient:Message(MT.Yellow,"After several heavy swings, the axe shatters into many fine pieces. Time for a new axe!");
									currclient:DeleteItemInInventory(Slot.Primary, 1, true);
									currclient:SummonItem(17833); -- Item: Broken Trial Taelosian Blood Axe
								elseif(currclient:GetItemIDAt(Slot.Primary)== 17759 ) then
									eq.target_global("berserk_epic_test17370", "1", "F", 0,currclient:CharacterID(),0);
									currclient:Message(MT.Yellow,"After raining down nearly two dozen blows you begin to notice small hairline fractures developing in the axe head. You think testing for this axe has been completed.");
									currclient:DeleteItemInInventory(Slot.Primary, 1, true);
									currclient:SummonItem(17898); -- Item: Damaged Trial Taelosian Blood Axe
								elseif(currclient:GetItemIDAt(Slot.Primary)==17700) then
									eq.target_global("berserk_epic_test17700", "1", "F", 0,currclient:CharacterID(),0);
									currclient:Message(MT.Yellow,"After many swings you can feel this axe is failing and think that it will fall apart at any moment. You think that testing for this axe has been completed.");
									currclient:DeleteItemInInventory(Slot.Primary, 1, true);
									currclient:SummonItem(17399); -- Item: Damaged Trial Taelosian Blood Axe
								elseif(currclient:GetItemIDAt(Slot.Primary)== 17370) then
									eq.target_global("berserk_epic_test16779", "1", "F", 0,currclient:CharacterID(),0);
									currclient:Message(MT.Yellow,"The rigors of battle have had no effect of this axe. Keras should be very pleased with the result of this particular axe.");
									currclient:DeleteItemInInventory(Slot.Primary, 1, true);
									currclient:SummonItem(18976); -- Item: Taelosian Alloy Blood Axe
								end
							end
						end
					end				
				end
			);
	end
end

function Protector_HP(e)
  if (e.hp_event == 75) then
	e.self:CastSpell(2047, e.self:GetTarget():GetID()); -- Spell: Death Shackles
	eq.set_timer("nuke", 36*1000);
	eq.signal(89195,75); -- NPC: A_Sebilite_Guardian
  end 
end

function Guardian_Signal(e)
	if(e.signal==75) then
		e.self:SetSpecialAbility(24, 0);
		e.self:SetSpecialAbility(25, 0);		
		local npc = eq.get_entity_list():GetMobByNpcTypeID(89194);
		if (npc.valid) then
			e.self:AddToHateList(npc:CastToMob():GetHateTop(),1);
		end
		e.self:CastSpell(4123, e.self:GetHateRandom():GetID()); --Blurring Focus
		eq.set_timer("blurringfocus",48*1000);
		e.self:CastSpell(6100, e.self:GetHateRandom():GetID()); --Curse of the Protector 		
		eq.set_timer("curseofprot",45*1000);		
		eq.set_timer("ch",math.random(2)*1000+10*1000); --Complete Heal Protector
	elseif(e.signal==1) then
		e.self:SetSpecialAbility(35, 0);
		e.self:SetSpecialAbility(39, 0);
	end
end

function Guardian_Timer(e)
	if(e.timer=="blurringfocus") then
		e.self:CastSpell(4123, e.self:GetHateRandom():GetID()); --Blurring Focus		
	elseif (e.timer=="curseofprot") then
		e.self:CastSpell(6100, e.self:GetHateRandom():GetID()); --Curse of the Protector 		
	elseif (e.timer=="ch") then
		local npc = eq.get_entity_list():GetMobByNpcTypeID(89194);	
		if (npc.valid) then
			e.self:CastSpell(13, npc:GetID(),1,10000); --Complete Heal
		end			
	end
end

function Protector_Combat(e)
  if e.joined then
	eq.set_timer("checkaxe",6000);
  end  
end

function Protector_Death(e)
	e.self:ForeachHateList(
		function(ent, hate, damage, frenzy)
			if(ent:IsClient()) then
				if(ent:CastToMob():GetClass() == Class.BERSERKER and damage > 0) then --berserker
					local currclient=ent:CastToClient();
					if(currclient:HasItem(17833) and currclient:HasItem(17898) and currclient:HasItem(17399) and currclient:HasItem(18976)) then
						currclient:Message(MT.Red,"Stepping back for a moment, you look over the axes that you have crafted. Two of them seem to be no more durable than any other axe you've seen, another is completely broken, yet the fourth catches your eye. The blade has nary a nick anywhere on it, the handle seemingly able to withstand immense amounts of punishment.");
						eq.target_global("berserk_epic", "4", "F", 0,currclient:CharacterID(),0);
						local qglobals = eq.get_qglobals(currclient);
						if(qglobals["berserk_epic_sebchest"] == nil or qglobals["berserk_epic_sebchest"] =="0") then	
							--eq.world_emote(15,"in global if ");
							eq.spawn2(283157,0,0,e.self:GetX(),e.self:GetY(),e.self:GetZ(),e.self:GetHeading()); -- #a chest (Epic 1.5)
							eq.target_global("berserk_epic_sebchest", "1", "F", 0,currclient:CharacterID(),0);
						end								
					end
				end
			end				
		end
	);
	eq.signal(89195,1); -- NPC: A_Sebilite_Guardian
end


function event_encounter_load(e)
  eq.register_npc_event('berserkerepic_1_5', Event.death_complete, 89193, Juggernaut_Death);
  eq.register_npc_event('berserkerepic_1_5', Event.timer,          89194, Protector_Timer);
  eq.register_npc_event('berserkerepic_1_5', Event.spawn,          89194, Protector_Spawn);
  eq.register_npc_event('berserkerepic_1_5', Event.spawn,          89195, Guardian_Spawn);  
  eq.register_npc_event('berserkerepic_1_5', Event.combat,         89194, Protector_Combat);
  eq.register_npc_event('berserkerepic_1_5', Event.hp,         	   89194, Protector_HP);  
  eq.register_npc_event('berserkerepic_1_5', Event.death, 		   89194, Protector_Death);
  eq.register_npc_event('berserkerepic_1_5', Event.timer,		   89195, Guardian_Timer);
  eq.register_npc_event('berserkerepic_1_5', Event.signal,	   	   89195, Guardian_Signal); 
  eq.register_npc_event('berserkerepic_1_5', Event.timer,          89195, Guardian_Timer);
end

-- 10th Ring War
-- Great Divide
-- 118167 Zrelik the Scout
--
-- When Event Starts:
-- - Zone Depops
-- - Extra Dwarf Defenders spawn to guard TODO: make these dwarves 
--   Player controalable.
-- - 13 waves of mobs will spawn in succession; each wave will have 
--   a wave master (Captain, General, Warlord) when the wave master 
--   dies; it will start a timer (5min) before the next wave spawns
-- - 14th wave is just Narandi.
-- - There are three locations in which the giants will spawn and
--   start pathing twards Thurgadin.
--
-- Fail Conditions:
-- - Any Giant reaches the final waypoint of their pathing (which is 
--   near Thurgain).
-- - Seneschal Aldikan dies
--
-- items: 1741, 1746, 1745, 1744, 1743, 1742, 18511

local current_wave_number;

-- This variable controls the time between waves; currently 5min.
local wave_cooldown_time = 5 * 60 * 1000;

function Stop_Event()
  -- Condition 1 is the general mobs in the zone
  eq.spawn_condition("greatdivide", 0, 1, 1);
  eq.spawn_condition("greatdivide", 0, 2, 0);
  eq.spawn_condition("greatdivide", 0, 3, 0);
  eq.spawn_condition("greatdivide", 0, 4, 0);
  eq.spawn_condition("greatdivide", 0, 5, 0);
  eq.spawn_condition("greatdivide", 0, 6, 0);
  eq.spawn_condition("greatdivide", 0, 7, 0);
  eq.spawn_condition("greatdivide", 0, 8, 0);
  eq.spawn_condition("greatdivide", 0, 9, 0);
  eq.spawn_condition("greatdivide", 0, 10, 0);
  eq.spawn_condition("greatdivide", 0, 11, 0);
  eq.spawn_condition("greatdivide", 0, 12, 0);
  eq.spawn_condition("greatdivide", 0, 13, 0);
  eq.spawn_condition("greatdivide", 0, 14, 0);
  eq.spawn_condition("greatdivide", 0, 15, 0);
  eq.spawn_condition("greatdivide", 0, 16, 0);
  eq.spawn_condition("greatdivide", 0, 17, 0);
  eq.spawn_condition("greatdivide", 0, 18, 0);
  eq.spawn_condition("greatdivide", 0, 19, 0);
  eq.spawn_condition("greatdivide", 0, 20, 0);
  eq.spawn_condition("greatdivide", 0, 21, 0);
end

function Master_Spawn(e)
  -- The first spawn condition to work with is 3; so 
  -- if we reset the event; we need to reset this to 3
  current_spawn_condition = 3;

  -- Reset all the spawn conditions to a clean state.
  Stop_Event();

end

function Start_Event()
  eq.spawn_condition("greatdivide", 0, 1, 0);
  eq.spawn_condition("greatdivide", 0, 2, 1);

  -- Signal the ringtemmaster to spawn the first wave...
  eq.signal(118173, 1); -- NPC: ringtenmaster

  -- Spawn the Dwarf Generals with spawn commands 
  -- so they aren't depopped when Narandi is killed
  -- and the zone is reset to normal mode.
  eq.spawn2(118169, 0, 0, -44, -792, 51, 230); -- NPC: Churn_the_Axeman
  eq.spawn2(118172, 0, 0, -37, -788, 51, 230); -- NPC: Kargin_the_Archer
  eq.spawn2(118171, 0, 0, -27, -788, 51, 230); -- NPC: Corbin_Blackwell
  eq.spawn2(118170, 0, 0, -17, -788, 51, 230); -- NPC: Dobbin_Crossaxe
  eq.spawn2(118168, 0, 0, -7,  -788, 51, 230); -- NPC: Garadain_Glacierbane
end

function Zrelik_Say(e)
  if (e.other:Admin() >= 80 and e.other:GetGM()) then
    if (e.message:findi('end')) then
      Stop_Event();

      eq.depop_all(118169);
      eq.depop_all(118171);
      eq.depop_all(118172);
      eq.depop_all(118170);
      eq.depop_all(118168);

    elseif (e.message:findi('start')) then
      Start_Event();

    end
  end
end

function Master_Signal(e)

  if (e.signal == 1) then
    eq.spawn_condition("greatdivide", 0, 3, 1);

  elseif (e.signal == 2) then 
    -- Stop wave timer (if its running)
    eq.stop_timer('wave_cooldown');
    eq.set_timer('wave_cooldown', wave_cooldown_time);

  end

end

function Master_Timer(e)
  if (e.timer == 'wave_cooldown') then
    eq.stop_timer(e.timer);

    current_spawn_condition = current_spawn_condition + 1;

    eq.spawn_condition("greatdivide", 0, current_spawn_condition, 1);
  end
end

function Seneschal_Spawn(e)
  e.self:Shout(" 'Good citizens of Thurgadin, hear me! Our city, our people, our very lives are in danger this day. The Kromrif are at this very moment marching towards us in an offensive they hope will bring about our demise...' ");

  e.self:Shout(" 'I hereby command, by authority of Dain Frostreaver the Fourth, that all able bodied Coldain fight to the death in defense of our land. Children, disabled citzens, and unseasoned travellers are advised to evacuate immediately!' ");

  e.self:Shout(" 'My fellow soldiers, take heart! For we are not alone in this endeavor. One among us, an outlander, has earned the title Hero of the Dain for valiant service to our people. This newcomer has brought with him allies that will fight alongside you to help bring about our victory.' ");

  e.self:Shout(" 'My friends... Brell did not place us here so many centuries ago to be slaughtered by these heathens. Nor did our forefather, Colin Dain, sacrifice himself simply to have us fail here now. Through these events we were brought to this day to test our strength and our faith.' ");

  e.self:Shout(" 'Will we be shackled together to slave away in Kromrif mines or will we stand united and feed these beasts Coldain blades? By Brell, I promise you, it is better to die on our feet than to live on our knees!' ");

  e.self:Shout(" 'TROOPS, TAKE YOUR POSITIONS!!' ");

end

function Seneschal_Death(e)
  -- Event Fail
  -- Pop Giants outside of Thurgadin
  -- Depop all the mobs in Thurgadin for 2hours.
  Stop_Event();
  eq.zone_emote(MT.Red, "The forces defending the Grand Citadel of Thurgadin have failed, the Kromrif have overrun the first and oldest race.  The age of the dwarf has come to an end...");

  -- Depop the Dwarf Generals if they are still alive.
  eq.depop_all(118169);
  eq.depop_all(118171);
  eq.depop_all(118172);
  eq.depop_all(118170);
  eq.depop_all(118168);
end

function WaveMaster_Death(e)
  -- Send a signal to the ringtenmaster that one of the WaveMasters has 
  -- died; start a 5min timer before the next wave is spawned.
  eq.signal(118173, 2); -- NPC: ringtenmaster
end

function Narandi_Spawn(e)
  e.self:Shout("So you have defeated my foot soldiers, now come and face me you vile, filthy dwarven rabble...");
end

function Narandi_Death(e)
  eq.zone_emote(MT.Red, 'No surprise the Age of the Dwarf continues with a Glorious victory of the Kromrif.');

  Stop_Event();
end

-- Hand in.: Shorn Head of Narandi (1741)
-- Get back: Crown of Narandi (1746)
-- Get back: Shorn Head of Narandi (1741)
function Churn_Trade(e)
  local item_lib = require("items");
  if (item_lib.check_turn_in(e.trade, {item1 = 1741})) then 
    e.other:SummonItem(1741); -- Item: Shorn Head of Narandi
    e.other:SummonItem(1746); -- Item: Crown of Narandi

    e.self:Emote("pries a crown from the head of Narandi, 'The halls of Thurgadin will echo with praises to you for as long as we grace the face of this land. May this crown serve you well. Honor through battle!' ");

    e.self:Depop();
  end

  item_lib.return_items(e.self, e.other, e.trade);
end

-- Hand in.: Shorn Head of Narandi (1741)
-- Get back: Eye of Narandi (1745)
-- Get back: Shorn Head of Narandi (1741)
function Kargin_Trade(e)
  local item_lib = require("items");
  if (item_lib.check_turn_in(e.trade, {item1 = 1741})) then 
    e.other:SummonItem(1741); -- Item: Shorn Head of Narandi
    e.other:SummonItem(1745); -- Item: Eye of Narandi

    e.self:Emote("picks up a stick and hits the back of the dismembered head with all his might, knocking one of its eyes out of the socket, 'Bastard killed my brother! Hope his ghost felt that one!' ");

    e.self:Depop();
  end

